def transform(grid):
    g=[row[:] for row in grid]
    H,W=len(g),len(g[0])
    # For each outlined rectangle, its empty interior is replaced by the interior pattern
    # of the corresponding patterned frame elsewhere, scaled only if dimensions match.
    colors=set(x for row in g for x in row)-{0}
    boxes={}
    for c in colors:
        pts=[(r,col) for r in range(H) for col in range(W) if g[r][col]==c]
        boxes[c]=(min(r for r,col in pts),max(r for r,col in pts),min(col for r,col in pts),max(col for r,col in pts))
    for fc,(r0,r1,c0,c1) in boxes.items():
        if not (all(g[r0][j]==g[r1][j]==fc for j in range(c0,c1+1)) and all(g[i][c0]==g[i][c1]==fc for i in range(r0,r1+1))):
            continue
        # Find color object with same bbox dimensions whose interior is patterned, then copy mask.
        for pc,(a,b,d,e) in boxes.items():
            if pc==fc or (b-a,c1-c0)!=(r1-r0,e-d): continue
            if any(g[i][j]==pc for i in range(a+1,b) for j in range(d+1,e)):
                for i in range(1,r1-r0):
                    for j in range(1,c1-c0):
                        if g[a+i][d+j]==pc: g[r0+i][c0+j]=fc
                break
    return g
