def transform(grid):
    g=[row[:] for row in grid]
    H,W=len(g),len(g[0])
    colors=set(x for row in g for x in row)-{0}
    boxes={}
    for c in colors:
        pts=[(r,j) for r in range(H) for j in range(W) if g[r][j]==c]
        boxes[c]=(min(r for r,j in pts),max(r for r,j in pts),min(j for r,j in pts),max(j for r,j in pts))
    # Empty rectangle frames are filled with pattern from the similarly sized patterned object.
    frames=[]; patterns=[]
    for c,(a,b,d,e) in boxes.items():
        rect=all(g[a][j]==g[b][j]==c for j in range(d,e+1)) and all(g[i][d]==g[i][e]==c for i in range(a,b+1))
        if rect:
            if all(g[i][j]==0 for i in range(a+1,b) for j in range(d+1,e)): frames.append((c,a,b,d,e))
            else: patterns.append((c,a,b,d,e))
        else: patterns.append((c,a,b,d,e))
    for fc,a,b,d,e in frames:
        for pc,r0,r1,c0,c1 in patterns:
            if (r1-r0,c1-c0)==(b-a,e-d):
                for i in range(1,b-a):
                    for j in range(1,e-d):
                        if grid[r0+i][c0+j]==pc:
                            g[a+i][d+j]=fc
                break
    return g
