def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    colors={x for row in grid for x in row if x}
    boxes={}
    for c in colors:
        pts=[(r,j) for r in range(h) for j in range(w) if grid[r][j]==c]
        boxes[c]=(min(r for r,j in pts),max(r for r,j in pts),min(j for r,j in pts),max(j for r,j in pts))
    frames=[]; sources=[]
    for c,(a,b,d,e) in boxes.items():
        rect=(all(grid[a][j]==grid[b][j]==c for j in range(d,e+1)) and all(grid[i][d]==grid[i][e]==c for i in range(a,b+1)))
        interior=[(i,j) for i in range(a+1,b) for j in range(d+1,e) if grid[i][j]==c]
        if rect and not interior: frames.append((c,a,b,d,e))
        elif not rect: sources.append((c,a,b,d,e))
    # Suppress transferring any object's existing pattern into other shapes unless an exact frame/source correspondence is established.
    # Copy source pattern only when the source is the matching-sized filled object.
    for fc,a,b,d,e in frames:
        ih,iw=b-a-1,e-d-1
        # Choose source object of matching outer dimensions. It may be an outlined object
        # with missing border segments (such as the tall/horizontal 1 and 6 shapes).
        candidates=[]
        for pc,r0,r1,c0,c1 in sources:
            ph,pw=r1-r0-1,c1-c0-1
            if (ph,pw)==(ih,iw): candidates.append((pc,r0,r1,c0,c1,False))
            elif (ph,pw)==(iw,ih): candidates.append((pc,r0,r1,c0,c1,True))
        if not candidates: continue
        pc,r0,r1,c0,c1,rot=candidates[0]
        for i in range(ih):
            for j in range(iw):
                if rot: si,sj=pw-1-j,i
                else: si,sj=i,j
                if grid[r0+1+si][c0+1+sj]==pc: out[a+1+i][d+1+j]=fc
    return out

