def transform(grid):
    # In each same-sized pair, copy the irregular interior mask into the hollow frame.
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    colors={v for row in grid for v in row if v}
    boxes={}
    for c in colors:
        pts=[(r,j) for r in range(h) for j in range(w) if grid[r][j]==c]
        boxes[c]=(min(r for r,j in pts),max(r for r,j in pts),min(j for r,j in pts),max(j for r,j in pts))
    frames=[]; sources=[]
    for c,(a,b,d,e) in boxes.items():
        rect=(all(grid[a][j]==grid[b][j]==c for j in range(d,e+1)) and all(grid[i][d]==grid[i][e]==c for i in range(a,b+1)))
        interior=[grid[i][j]==c for i in range(a+1,b) for j in range(d+1,e)]
        if rect and not any(interior): frames.append((c,a,b,d,e))
        else: sources.append((c,a,b,d,e))
    for fc,a,b,d,e in frames:
        ih,iw=b-a-1,e-d-1
        for pc,r0,r1,c0,c1 in sources:
            ph,pw=r1-r0-1,c1-c0-1
            if (ph,pw)==(ih,iw):
                for i in range(ih):
                    for j in range(iw):
                        if grid[r0+1+i][c0+1+j]==pc: out[a+1+i][d+1+j]=fc
                break
            if (ph,pw)==(iw,ih):
                for i in range(ih):
                    for j in range(iw):
                        if grid[r0+1+(pw-1-j)][c0+1+i]==pc: out[a+1+i][d+1+j]=fc
                break
    return out
