        boxes[c]=(min(r for r,j in pts),max(r for r,j in pts),min(j for r,j in pts),max(j for r,j in pts))
    # Empty four-sided frames receive the pattern contained in the same-sized nonempty object.
    frames=[]; sources=[]
    for c,(a,b,d,e) in boxes.items():
        rectangle=(all(grid[a][j]==grid[b][j]==c for j in range(d,e+1)) and all(grid[i][d]==grid[i][e]==c for i in range(a,b+1)))
